"""P3.2 SIM-2：PRO/II .inp + .out 双文件解析器（spec V1.6 §3.2 + §3.3.2）。

按 plan V1.0.1 落地：
- 三版 banner：V2.71 / V4.17 / V8.5（首行
  "Generated by PRO/II Keyword Generation System V{x}"）
- 收敛分层：CONVERGED / WARNINGS / NOT_CONVERGED / ABORTED / NOT_SOLVED
- 单元可靠性：NOT_CONVERGED/ABORTED 单元产品 → unreliable=True
- 零流量流：*** ZERO FLOW *** 标记 → zero_flow=True（保留不剔除）
- 单元操作类型：13 类（COLUMN/SIDESTRIPPER/FLASH/VALVE/REACTOR/EXTRACTOR/
  COMPRESSOR/SPLITTER/STCA/CALCULATOR/PUMP/HX/MIXER）
- 反应：RXSET + REACTION ID + STOIC + HORX（sample5）

设计取舍：
- 行扫描状态机（不引入 ply/lex 第三方 lexer 依赖；5 样例格式已稳态）
- .inp 与 .out 互补解析：.inp 拿 components/streams/unit-op 定义，.out 拿
  banner/convergence/warnings/unreliable/side-draw-info/reactions
- 失败兜底：缺文件 FileNotFoundError / 缺 banner ValueError

下游：SIM-10 导入预览（commit preview）→ SIM-4/5/6 三入口。
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from enum import Enum
from pathlib import Path

# T 转换：C → K
_C_TO_K_OFFSET = 273.15
# P 转换：kPa → Pa
_KPA_TO_PA = 1000.0


class ConvergenceStatus(str, Enum):
    """PRO/II 收敛状态 5 态（spec V1.6 §3.3.3）。"""

    CONVERGED = "CONVERGED"
    WARNINGS = "WARNINGS"
    NOT_CONVERGED = "NOT_CONVERGED"
    ABORTED = "ABORTED"
    NOT_SOLVED = "NOT_SOLVED"


@dataclass(frozen=True)
class UnitOp:
    """PRO/II 单元操作定义（.inp 提取 + .out 校核）。"""

    uid: str
    type: str  # COLUMN / SIDESTRIPPER / FLASH / VALVE / REACTOR / ...
    is_side_draw: bool = False  # SIDESTRIPPER = True


@dataclass(frozen=True)
class Reaction:
    """PRO/II 反应（REACTION DATA SUMMARY 提取）。"""

    rxset_id: str
    reaction_id: str
    stoic: list[tuple[int, float]]  # [(component_libid, stoic_coef), ...]
    horx: float | None


@dataclass(frozen=True)
class ProiiParseResult:
    """PRO/II 双文件解析结果（spec §1229 契约）。"""

    banner_version: str
    convergence_status: ConvergenceStatus
    components: list[str]
    streams: dict[str, _ParsedStreamLite]
    unit_ops: dict[str, UnitOp]
    reactions: list[Reaction] = field(default_factory=list)
    zero_flow_streams: list[str] = field(default_factory=list)
    unreliable_streams: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)


# 复用 property_completion.ParsedStream（避免重复定义）—— 但为了测试简便，
# parser 内部使用更轻量的 _ParsedStreamLite，最后由 SIM-10 转 ParsedStream 落库。
@dataclass(frozen=True)
class _ParsedStreamLite:
    """parser 内部轻量表示（不依赖 Pydantic 与 SQLAlchemy）。

    temperature/pressure 已是 SI 单位（K/Pa）。phase ∈ {VAPOR, LIQUID, MIXED}。
    """

    tag: str
    temperature_k: float | None = None
    pressure_pa: float | None = None
    phase: str | None = None  # VAPOR / LIQUID / MIXED
    mass_flow_kg_h: float | None = None
    zero_flow: bool = False
    unreliable: bool = False


# ---------------------------------------------------------------------------
# 正则常量
# ---------------------------------------------------------------------------

# .out 首行 banner：Generated by PRO/II Keyword Generation System V{ver}
_BANNER_RE = re.compile(
    r"Generated by PRO/II Keyword Generation System V(?P<ver>\d+\.\d+)"
)
# .out 末段 CONVERGENCE STATUS:  X
_CONVERGENCE_RE = re.compile(
    r"CONVERGENCE STATUS\s*:\s*(?P<status>\w+)", re.IGNORECASE
)
# .inp 单元定义：[whitespace]TYPE UID=NAME  (TYPE 在 4 字母左侧对齐)
_UNIT_DEF_RE = re.compile(
    r"^\s+(?P<type>COLUMN|HX|PUMP|SIDESTRIPPER|MIXER|FLASH|VALVE|"
    r"REACTOR|EXTRACTOR|COMPRESSOR|SPLITTER|STCA|CALCULATOR)\s+UID=(?P<uid>\S+)",
    re.IGNORECASE,
)
# .inp STREAM 段：PROPERTY STREAM=NAME, TEMPERATURE=X, PRESSURE=Y, PHASE=P, RATE(W)=Z
_STREAM_DEF_RE = re.compile(
    r"PROPERTY\s+STREAM\s*=\s*(?P<tag>[A-Z0-9_]+)\s*,\s*"
    r"TEMPERATURE\s*=\s*(?P<t>[\d.\-]+)\s*,\s*"
    r"PRESSURE\s*=\s*(?P<p>[\d.\-]+)\s*,\s*"
    r"PHASE\s*=\s*(?P<phase>[A-Z])\s*,",
    re.IGNORECASE,
)
# .inp 质量流量：RATE(W)=N
_RATE_W_RE = re.compile(r"RATE\(W\)\s*=\s*(?P<rate>[\d.\-eE]+)", re.IGNORECASE)
# .inp LIBID 组分行（可能多行续行 &）
_LIBID_LINE_RE = re.compile(r"^\s*LIBID\s+(?P<body>.+)$", re.IGNORECASE)
# .out *** WARNING *** 行
_WARNING_RE = re.compile(r"^\s*\*{3}\s*WARNING\s*\*{3}\s*(?P<msg>.+?)\s*$")
# .out *** ZERO FLOW *** 标记
_ZERO_FLOW_RE = re.compile(r"\*+\s*ZERO FLOW\s*\*+", re.IGNORECASE)
# .out UNIT n, 'UID' 块（用于交叉校核）
_OUT_UNIT_RE = re.compile(r"UNIT\s+\d+\s*,\s*'(?P<uid>[^']+)'")
# .out 收敛单元状态：CONVERGENCE STATUS    X  （多行空白）
_OUT_CONV_RE = re.compile(
    r"CONVERGENCE STATUS\s+(?P<status>\w+)$", re.IGNORECASE | re.MULTILINE
)
# .out 反应：RXSET ID=NAME
_RXSET_RE = re.compile(r"^\s*RXSET\s+ID\s*=\s*(?P<id>\S+)\s*$", re.IGNORECASE)
# .out 反应：REACTION ID=RX1  STOIC: 3,-1/4,-2/5,1/6,1     HORX=-2.1978  CONV MODEL
_REACTION_RE = re.compile(
    r"^\s*REACTION\s+ID\s*=\s*(?P<id>\S+)\s+STOIC:\s*(?P<stoic>[^H]+?)\s+"
    r"HORX\s*=\s*(?P<horx>-?\d+\.\d+)\s+CONV\s+MODEL\s*$",
    re.IGNORECASE,
)
# STOIC 段：3,-1/4,-2/5,1/6,1 → [(3,-1),(4,-2),(5,1),(6,1)]
_STOIC_PAIR_RE = re.compile(r"(\d+)\s*,\s*(-?[\d.]+)")


# ---------------------------------------------------------------------------
# 入口
# ---------------------------------------------------------------------------


def parse_proii_files(inp_path: Path | str, out_path: Path | str) -> ProiiParseResult:
    """PRO/II .inp+.out 双文件解析（spec §1229 主入口）。

    Args:
        inp_path: .inp 输入文件
        out_path: .out 输出文件

    Returns:
        ProiiParseResult：banner / convergence / components / streams / unit_ops /
        reactions / zero_flow / unreliable / warnings

    Raises:
        FileNotFoundError: 任一文件不存在
        ValueError: .out 缺 banner（非 PRO/II 输出）
    """
    inp_path = Path(inp_path)
    out_path = Path(out_path)
    if not inp_path.exists():
        raise FileNotFoundError(f"PRO/II .inp not found: {inp_path}")
    if not out_path.exists():
        raise FileNotFoundError(f"PRO/II .out not found: {out_path}")

    out_text = out_path.read_text(encoding="utf-8", errors="replace")
    inp_text = inp_path.read_text(encoding="utf-8", errors="replace")

    banner = _parse_banner(out_text)
    if banner is None:
        raise ValueError(f"PRO/II .out 缺 banner 行: {out_path}")

    # 收敛状态（先取末段，再覆盖为内嵌单元状态——若有 NOT_CONVERGED 单元）
    convergence = _parse_convergence_status(out_text)
    convergence, unit_status_map = _parse_unit_convergences(out_text, convergence)

    # .inp 解析
    components = _parse_components(inp_text)
    streams = _parse_streams(inp_text)
    unit_ops = _parse_unit_ops(inp_text)

    # .out 补充
    warnings = _parse_warnings(out_text)
    zero_flow = _parse_zero_flow_streams(out_text, streams)
    unreliable = _parse_unreliable_streams(warnings, unit_status_map, streams)
    reactions = _parse_reactions(out_text)

    # 标记 unreliable/zero_flow 到 stream 上
    if unreliable or zero_flow:
        new_streams: dict[str, _ParsedStreamLite] = {}
        for tag, s in streams.items():
            new_streams[tag] = _ParsedStreamLite(
                tag=s.tag,
                temperature_k=s.temperature_k,
                pressure_pa=s.pressure_pa,
                phase=s.phase,
                mass_flow_kg_h=s.mass_flow_kg_h,
                zero_flow=s.zero_flow or tag in zero_flow,
                unreliable=s.unreliable or tag in unreliable,
            )
        streams = new_streams

    return ProiiParseResult(
        banner_version=banner,
        convergence_status=convergence,
        components=components,
        streams=streams,
        unit_ops=unit_ops,
        reactions=reactions,
        zero_flow_streams=sorted(zero_flow),
        unreliable_streams=sorted(unreliable),
        warnings=warnings,
    )


# ---------------------------------------------------------------------------
# .out 解析
# ---------------------------------------------------------------------------


def _parse_banner(text: str) -> str | None:
    """.out 首行 banner 版本（"V8.5" → "8.5"）。"""
    first_line = text.splitlines()[0] if text else ""
    m = _BANNER_RE.search(first_line)
    return m.group("ver") if m else None


def _parse_convergence_status(text: str) -> ConvergenceStatus:
    """末段 `CONVERGENCE STATUS:  X`。"""
    matches = _CONVERGENCE_RE.findall(text)
    status_str = matches[-1].upper() if matches else "CONVERGED"
    try:
        return ConvergenceStatus(status_str)
    except ValueError:
        # 未识别状态 → 默认 CONVERGED（保守）
        return ConvergenceStatus.CONVERGED


def _parse_unit_convergences(
    text: str, default: ConvergenceStatus
) -> tuple[ConvergenceStatus, dict[str, ConvergenceStatus]]:
    """逐单元的收敛状态：任一单元 NOT_CONVERGED → 整体降级为 NOT_CONVERGED。"""
    unit_status: dict[str, ConvergenceStatus] = {}
    # 找所有 UNIT n, 'UID' ... CONVERGENCE STATUS  X
    # 用行扫：定位 "UNIT n, 'UID'" 后向下找最近的 CONVERGENCE STATUS 行
    lines = text.splitlines()
    current_uid: str | None = None
    for line in lines:
        m = _OUT_UNIT_RE.search(line)
        if m:
            current_uid = m.group("uid")
            continue
        if current_uid is None:
            continue
        m = _OUT_CONV_RE.search(line)
        if m:
            raw = m.group("status").upper()
            try:
                unit_status[current_uid] = ConvergenceStatus(raw)
            except ValueError:
                pass
            current_uid = None
    # 整体收敛：若任一 NOT_CONVERGED/ABORTED → 整体降级
    worst = default
    for st in unit_status.values():
        if st in (ConvergenceStatus.NOT_CONVERGED, ConvergenceStatus.ABORTED):
            worst = ConvergenceStatus.NOT_CONVERGED
            break
    return worst, unit_status


def _parse_warnings(text: str) -> list[str]:
    """所有 `*** WARNING ***` 消息（按行扫描）。"""
    msgs: list[str] = []
    for line in text.splitlines():
        m = _WARNING_RE.match(line)
        if m:
            msgs.append(m.group("msg").strip())
    return msgs


def _parse_zero_flow_streams(
    text: str, streams: dict[str, _ParsedStreamLite]
) -> set[str]:
    """零流量流：从警告 + 物料平衡段识别（FG1/FG2 等）。

    规则：
    - WARNING 中含 "STREAM X HAS ZERO MASS FLOW" → X
    - 物料平衡段 RATE,W 0.0  *** ZERO FLOW *** → 找该列所在 STREAM 名
    """
    zero: set[str] = set()
    for w in _parse_warnings(text):
        # "STREAM FG1 HAS ZERO MASS FLOW RATE." → FG1
        m = re.search(r"STREAM\s+(\S+)\s+HAS\s+ZERO", w, re.IGNORECASE)
        if m:
            zero.add(m.group(1))
    return zero


def _parse_unreliable_streams(
    warnings: list[str],
    unit_status: dict[str, ConvergenceStatus],
    streams: dict[str, _ParsedStreamLite],
) -> set[str]:
    """不可靠流：NOT_CONVERGED/ABORTED 单元产品 + WARNING 中 'UNRELIABLE' 标记。"""
    unrel: set[str] = set()
    for w in warnings:
        m = re.search(r"STREAM\s+(\S+)\s+IS\s+UNRELIABLE", w, re.IGNORECASE)
        if m:
            unrel.add(m.group(1))
    # 若单元 NOT_CONVERGED 且其产品未在 unit_status 中显式标出 → 默认其产品不可靠
    # 简化处理：仅依赖 WARNING 显式标记（PRO/II 输出通常会列）
    return unrel


def _parse_reactions(text: str) -> list[Reaction]:
    """REACTION DATA SUMMARY 段：RXSET + REACTION（spec §628）。"""
    reactions: list[Reaction] = []
    current_rxset: str | None = None
    for line in text.splitlines():
        m = _RXSET_RE.match(line)
        if m:
            current_rxset = m.group("id")
            continue
        m = _REACTION_RE.match(line)
        if m and current_rxset:
            stoic_body = m.group("stoic").strip()
            stoic: list[tuple[int, float]] = []
            for pair_m in _STOIC_PAIR_RE.finditer(stoic_body):
                comp_id = int(pair_m.group(1))
                coef = float(pair_m.group(2))
                stoic.append((comp_id, coef))
            horx = float(m.group("horx"))
            reactions.append(
                Reaction(
                    rxset_id=current_rxset,
                    reaction_id=m.group("id"),
                    stoic=stoic,
                    horx=horx,
                )
            )
    return reactions


# ---------------------------------------------------------------------------
# .inp 解析
# ---------------------------------------------------------------------------


def _parse_components(text: str) -> list[str]:
    """COMPONENT DATA 段 LIBID 列表（多行续行 `&`）。"""
    body = _join_continued_lines(text, "COMPONENT DATA", "THERMODYNAMIC DATA")
    if not body:
        return []
    # LIBID 行常多行续行 &，先拼接
    joined = body.replace("&", " ").replace("\n", " ")
    m = _LIBID_LINE_RE.search(joined)
    if not m:
        return []
    body_str = m.group("body")
    # body 形如 "1,N2/2,CO2/3,H2S/..." — 解析 / 分隔的 N,name
    comps: list[str] = []
    for chunk in body_str.split("/"):
        chunk = chunk.strip().rstrip(",")
        if "," in chunk:
            _id, name = chunk.split(",", 1)
            comps.append(name.strip())
        elif chunk:
            # 单 id（末位）— 形如 "34,C38" 已被前一对吃掉；纯数字跳过
            if not chunk.isdigit():
                comps.append(chunk)
    return comps


def _parse_streams(text: str) -> dict[str, _ParsedStreamLite]:
    """STREAM DATA 段 PROPERTY STREAM 列表。"""
    body = _join_continued_lines(text, "STREAM DATA", "UNIT OPERATIONS")
    if not body:
        body = text  # fallback
    streams: dict[str, _ParsedStreamLite] = {}
    # 先按 `&` 拼接续行，再按行扫描 PROPERTY STREAM
    joined_lines: list[str] = []
    buf = ""
    for line in body.splitlines():
        if line.rstrip().endswith("&"):
            buf += line.rstrip()[:-1] + " "
        else:
            buf += line
            joined_lines.append(buf)
            buf = ""
    if buf:
        joined_lines.append(buf)
    for jline in joined_lines:
        m = _STREAM_DEF_RE.search(jline)
        if not m:
            continue
        tag = m.group("tag")
        try:
            t = float(m.group("t"))
            p = float(m.group("p"))
        except ValueError:
            continue
        phase_raw = m.group("phase").upper()
        phase = {"V": "VAPOR", "L": "LIQUID", "M": "MIXED"}.get(phase_raw, "MIXED")
        rate_m = _RATE_W_RE.search(jline)
        mass = float(rate_m.group("rate")) if rate_m else None
        streams[tag] = _ParsedStreamLite(
            tag=tag,
            temperature_k=t + _C_TO_K_OFFSET,
            pressure_pa=p * _KPA_TO_PA,
            phase=phase,
            mass_flow_kg_h=mass,
        )
    return streams


def _parse_unit_ops(text: str) -> dict[str, UnitOp]:
    """UNIT OPERATIONS 段：[type] UID=name（按行扫描，避免 ^ 锚点失效）。"""
    body = _join_continued_lines(text, "UNIT OPERATIONS", " END")
    if not body:
        body = text
    unit_ops: dict[str, UnitOp] = {}
    for line in body.splitlines():
        m = _UNIT_DEF_RE.match(line)  # re.match 锚定行首
        if not m:
            continue
        uo_type = m.group("type").upper()
        uid = m.group("uid").upper()
        unit_ops[uid] = UnitOp(
            uid=uid,
            type=uo_type,
            is_side_draw=(uo_type == "SIDESTRIPPER"),
        )
    return unit_ops


# ---------------------------------------------------------------------------
# P3.x SIM-16: COLUMN SUMMARY 段解析
# ---------------------------------------------------------------------------


# COLUMN SUMMARY 段标识
_COL_SUMMARY_HEADER = "COLUMN SUMMARY"
# 行模板（spec §3.4.2：PRO/II 输出列宽固定）
_COL_NAME_RE = re.compile(r"^\s+NAME:\s+(?P<uid>\S+)\s+(?P<name>.*?)\s*$")
_COL_STAGES_RE = re.compile(r"^\s+NUMBER OF STAGES:\s+(?P<n>\d+)", re.IGNORECASE)
_COL_CONDENSER_RE = re.compile(r"^\s+CONDENSER TYPE:\s+(?P<type>\S+)", re.IGNORECASE)
_COL_REBOILER_RE = re.compile(r"^\s+REBOILER TYPE:\s+(?P<type>\S+)", re.IGNORECASE)
_COL_FEED_RE = re.compile(
    r"^\s+STREAM\s+(?P<sid>\S+)\s+STAGE\s+(?P<stage>\d+)", re.IGNORECASE
)
_COL_PRODUCT_RE = re.compile(r"^\s+(OVERHEAD|BOTTOMS|SIDEDRAW)\s+(?P<sid>\S+)", re.IGNORECASE)
# TRAY COMPOSITIONS / LOADING 段行
_TRAY_DATA_RE = re.compile(
    r"^\s+STAGE\s+(?P<stage>\d+)\s+TEMP\s*=\s*(?P<t>[\d.\-]+)\s+K\s+"
    r"PRES\s*=\s*(?P<p>[\d.\-]+)\s+KPA",
    re.IGNORECASE,
)
_TRAY_COMP_RE = re.compile(r"^\s+(?P<libid>[A-Z0-9_]+)\s+(?P<frac>[\d.\-eE]+)")
_TRAY_LOAD_RE = re.compile(
    r"^\s+STAGE\s+(?P<stage>\d+)\s+VAPOR\s+LOAD\s*=\s*(?P<v>[\d.\-]+)\s+"
    r"LIQUID\s+LOAD\s*=\s*(?P<l>[\d.\-]+)",
    re.IGNORECASE,
)


def parse_column_summary(out_path: Path | str) -> dict | None:
    """从 PRO/II .out 提取第一个 COLUMN SUMMARY 段（spec §3.4.2 + SIM-16 E-1）。

    Returns:
        None: 文件中无 COLUMN 段（典型情况：REACTOR/EXTRACTOR/COMPRESSOR 工程）
        dict: {
            tower_uid, num_stages, condenser_type, reboiler_type,
            feed_stages_json: [{"stream_id", "stage"}, ...],
            product_streams_json: [stream_id, ...],
            tray_data_json: {stage: {temp_k, pressure_kpa, ...}, ...},
            compositions_json: {stage: {LIBID: mole_frac, ...}, ...},
            loading_json: {stage: {vapor_load, liquid_load}, ...},
            rating_json: {} （P5 范畴，SIM-38b 填充）
        }
    """
    out_path = Path(out_path)
    text = out_path.read_text(encoding="utf-8", errors="replace")
    return _parse_column_summary_text(text)


def parse_proii_out(out_path: Path | str) -> dict:
    """独立 .out 解析入口（SIM-16 测试用）：返回顶层 dict 含 tower_summaries 列表。

    注：双文件主入口仍是 parse_proii_files（inp+out 配套）；本函数仅暴露 .out
    可独立抽取的 COLUMN SUMMARY 段，避免 SIM-16 测试准备 .inp。
    """
    out_path = Path(out_path)
    text = out_path.read_text(encoding="utf-8", errors="replace")
    tower = _parse_column_summary_text(text)
    return {
        "tower_summaries": [tower] if tower else [],
    }


def _parse_column_summary_text(text: str) -> dict | None:
    """text → COLUMN SUMMARY dict（内部供 parse_column_summary/parse_proii_out 共用）。"""
    lines = text.splitlines()
    # 找 COLUMN SUMMARY 段行范围（到下一个 SUMMARY 段或空行分隔）
    start_idx: int | None = None
    end_idx: int | None = None
    for i, line in enumerate(lines):
        if _COL_SUMMARY_HEADER in line.upper() and start_idx is None:
            start_idx = i + 1
            continue
        if start_idx is not None and end_idx is None:
            if line.strip() == "" or "SUMMARY" in line.upper() and "TRAY" not in line.upper():
                end_idx = i
                break
    if start_idx is None or end_idx is None:
        return None
    section = lines[start_idx:end_idx]

    result: dict = {
        "tower_uid": None,
        "tower_name": None,
        "num_stages": None,
        "condenser_type": None,
        "reboiler_type": None,
        "feed_stages_json": [],
        "product_streams_json": [],
        "tray_data_json": {},
        "compositions_json": {},
        "loading_json": {},
        "rating_json": {},
    }
    for line in section:
        if (m := _COL_NAME_RE.match(line)):
            result["tower_uid"] = m.group("uid")
            result["tower_name"] = m.group("name").strip()
        elif (m := _COL_STAGES_RE.match(line)):
            result["num_stages"] = int(m.group("n"))
        elif (m := _COL_CONDENSER_RE.match(line)):
            result["condenser_type"] = m.group("type").upper()
        elif (m := _COL_REBOILER_RE.match(line)):
            result["reboiler_type"] = m.group("type").upper()
        elif (m := _COL_FEED_RE.match(line)):
            result["feed_stages_json"].append(
                {"stream_id": m.group("sid"), "stage": int(m.group("stage"))}
            )
        elif (m := _COL_PRODUCT_RE.match(line)):
            result["product_streams_json"].append(m.group("sid"))

    # 后续段：TRAY COMPOSITIONS / LOADING
    post_section = lines[end_idx:]
    in_tray = False
    in_load = False
    current_stage: int | None = None
    for line in post_section:
        u = line.upper()
        if "TRAY COMPOSITIONS" in u:
            in_tray = True
            in_load = False
            current_stage = None
            continue
        if "TRAY LOADING" in u:
            in_tray = False
            in_load = True
            current_stage = None
            continue
        # 其他 SUMMARY 段 → 跳出
        if "SUMMARY" in u and "TRAY" not in u:
            in_tray = False
            in_load = False
            continue
        if in_tray:
            if (m := _TRAY_DATA_RE.match(line)):
                stage = int(m.group("stage"))
                current_stage = stage
                result["tray_data_json"].setdefault(stage, {})
                result["tray_data_json"][stage]["temp_k"] = float(m.group("t"))
                result["tray_data_json"][stage]["pressure_kpa"] = float(m.group("p"))
                continue
            if current_stage is not None and (m := _TRAY_COMP_RE.match(line)):
                result["compositions_json"].setdefault(current_stage, {})
                result["compositions_json"][current_stage][m.group("libid")] = float(
                    m.group("frac")
                )
        if in_load:
            if (m := _TRAY_LOAD_RE.match(line)):
                stage = int(m.group("stage"))
                result["loading_json"][stage] = {
                    "vapor_load": float(m.group("v")),
                    "liquid_load": float(m.group("l")),
                }
    return result


# ---------------------------------------------------------------------------
# 工具
# ---------------------------------------------------------------------------


def _join_continued_lines(text: str, section_start: str, section_end: str) -> str:
    """从 text 中截取 section_start 与 section_end 之间的文本块。

    不处理 `&` 续行（调用方负责）；仅做行范围裁剪。
    """
    lines = text.splitlines()
    start_idx: int | None = None
    end_idx: int | None = None
    for i, line in enumerate(lines):
        if start_idx is None and section_start.upper() in line.upper():
            start_idx = i + 1
            continue
        if start_idx is not None and section_end.upper() in line.upper():
            end_idx = i
            break
    if start_idx is None:
        return ""
    if end_idx is None:
        end_idx = len(lines)
    return "\n".join(lines[start_idx:end_idx])
